actions.script:
def fail = { String message -> revision = [success:false,error:message] }
if (!(moduleId in ['pos','kot']) || (!kotId && (moduleId != 'pos' || !transactionId))) {
    fail('Choose an issued bill to revise.'); return
}
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameter('moduleId',moduleId).call()
if (access.canWrite != true) { fail('Billing write access is required.'); return }
def txId = transactionId
def org
if (kotId) {
    def history = ec.service.sync().name('zenith.pos.KotServices.get#HistoryBill')
        .parameters([sessionId:sessionId,kotId:kotId]).call()?.bill
    if (!history) { fail('This bill is unavailable for the current terminal and login.'); return }
    txId = history.transactionId
    org = history.organizationPartyId
} else {
    def scope = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameter('transactionId',txId).call()
    if (!scope.allowed) { fail('This bill is unavailable for the current terminal and login.'); return }
    org = scope.organizationPartyId
}
def reason = (editReason ?: '').trim()
if (!reason) { fail('Enter a reason before saving or printing an edited bill.'); return }
if (reason.length() > 500) { fail('Keep the edit reason under 500 characters.'); return }
def txn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',txId)
    .condition('organizationPartyId',org).forUpdate(true).one()
if (txn?.statusId != 'PtCompleted') { fail('Transaction not found or not editable'); return }
def freeState
try {
    // Validate the entire batch before writing so an invalid edit cannot leave a partial revision.
    def changes
    try {
        changes = editOps ? new groovy.json.JsonSlurper().parseText(editOps) :
            [[type:editType, seq:editItemSeqId, newQty:newQty, newPrice:newPrice,
              productId:addProductId, addQty:addQty]]
    } catch (Exception ignored) { changes = null }
    if (!(changes instanceof List) || !changes || changes.size() > 50 || changes.any { !(it instanceof Map) }) {
        fail('Choose 1 to 50 valid bill changes.'); return
    }
    def originalItems = ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId', txId).list()
    def originalSeqs = originalItems.collect { it.itemSeqId } as Set
    def billHasTax = originalItems.any { ((it.totalTaxAmount ?: 0) as BigDecimal) > 0 }
    int nextItemSeq = (originalItems.collect { it.itemSeqId as int }.max() ?: 0) as int
    def removedSeqs = [] as Set
    int addedCount = 0
    for (def op : changes) {
        def type = op.type
        if (!['QTY_CHANGE','PRICE_CHANGE','ITEM_ADDED','ITEM_REMOVED'].contains(type)) {
            fail('Choose a valid amendment.'); return
        }
        if (type == 'ITEM_ADDED') {
            def prod = op.productId ? ec.entity.find('mantle.product.Product').condition('productId', op.productId).one() : null
            if (!prod || prod.ownerPartyId != txn.organizationPartyId) {
                fail('Choose a product from this organization.'); return
            }
            if (op.newPrice == null || !op.newPrice.toString().trim()) {
                def configuredPrice = (prod.mrpAmount ?: 0) as BigDecimal
                if (configuredPrice <= 0) {
                    def priceRow = ec.entity.find('mantle.product.ProductPrice').condition('productId',prod.productId)
                        .condition('priceTypeEnumId','PptList').orderBy('-lastUpdatedStamp').one()
                    if (!priceRow) priceRow = ec.entity.find('mantle.product.ProductPrice').condition('productId',prod.productId)
                        .condition('priceTypeEnumId','PptCurrent').orderBy('-lastUpdatedStamp').one()
                    configuredPrice = (priceRow?.price ?: 0) as BigDecimal
                }
                if (configuredPrice <= 0) { fail('Set a product price above ₹0 before adding it to an issued bill.'); return }
            }
            addedCount++
        } else if (!originalSeqs.contains(op.seq) || removedSeqs.contains(op.seq)) {
            fail('An edited item is missing or was already removed. Reload the bill.'); return
        }
        if (type == 'ITEM_REMOVED') removedSeqs.add(op.seq)
        if (type in ['QTY_CHANGE','PRICE_CHANGE','ITEM_ADDED']) {
            def raw = type == 'QTY_CHANGE' ? op.newQty : type == 'PRICE_CHANGE' ? op.newPrice : (op.addQty != null ? op.addQty : '1')
            def amount
            try { amount = new BigDecimal(raw.toString()) }
            catch (Exception ignored) { fail('Enter a valid quantity or price.'); return }
            if ((type == 'PRICE_CHANGE' && (amount <= 0 || amount.scale() > 2)) ||
                (type != 'PRICE_CHANGE' && (amount <= 0 || amount.scale() > 3))) {
                fail('Use a positive quantity (up to 3 decimals) or a price above ₹0 (up to 2 decimals).'); return
            }
            if (type == 'ITEM_ADDED' && op.newPrice != null && op.newPrice.toString().trim()) {
                def addPrice
                try { addPrice = new BigDecimal(op.newPrice.toString()) }
                catch (Exception ignored) { fail('Enter a valid new-item price.'); return }
                if (addPrice <= 0 || addPrice.scale() > 2) { fail('New-item price must be above ₹0 with up to 2 decimals.'); return }
            }
        }
    }
    if (originalItems.size() - removedSeqs.size() + addedCount < 1) {
        fail('An issued bill must retain at least one item. Void it instead.'); return
    }
    for (def editOp : changes) {
        def editType = editOp.type
        def itemSeqId = editOp.seq
        def editedValue = editType == 'QTY_CHANGE' ? new BigDecimal(editOp.newQty.toString()) :
            editType == 'PRICE_CHANGE' ? new BigDecimal(editOp.newPrice.toString()) :
            editType == 'ITEM_ADDED' ? new BigDecimal((editOp.addQty != null ? editOp.addQty : '1').toString()) : null
        def currentTxn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId', txId).one()
        def oldGrand = (currentTxn.grandTotal ?: 0) as BigDecimal
        def invAdjProduct = null; def invAdjQty = BigDecimal.ZERO
        def _addedSeqId = null
        if (editType == 'QTY_CHANGE') {
            def item = ec.entity.find("zenith.erp.pos.PosTransactionItem")
                .condition("transactionId", txId).condition("itemSeqId", itemSeqId).one()
            if (!item) throw new IllegalStateException('Item not found; reload the bill.')
            def oldQty = item.quantity as BigDecimal
            def newQty = editedValue
            invAdjProduct = item.productId; invAdjQty = oldQty - newQty
            def up = (item.unitPrice ?: 0) as BigDecimal
            def dp = (item.discountPercent ?: 0) as BigDecimal
            def ls = newQty * up
            def da = ls * dp / 100
            def originalNet=((item.quantity ?: 0) as BigDecimal)*((item.unitPrice ?: 0) as BigDecimal)-((item.discountAmount ?: 0) as BigDecimal)
            def taxableFraction=originalNet>0 ? ((item.taxableAmount ?: 0) as BigDecimal)/originalNet : BigDecimal.ONE
            def ta = (ls - da) * taxableFraction
            def taxR = BigDecimal.ZERO
            if (item.totalTaxAmount != null && item.taxableAmount != null && (item.taxableAmount as BigDecimal) != 0) {
                taxR = (item.totalTaxAmount as BigDecimal) / (item.taxableAmount as BigDecimal)
            }
            def tt = ta * taxR
            def lt = ta + tt
            ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")
                .parameters([transactionId:txId, itemSeqId:itemSeqId,
                    quantity:newQty, discountAmount:da, taxableAmount:ta,
                    totalTaxAmount:tt, lineTotal:lt]).call()
            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")
                .parameters([transactionId:txId]).call()
            def txnAfter = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
            ec.service.sync().name("create#zenith.erp.pos.PosTransactionAmendment")
                .parameters([transactionId:txId,
                    amendedByPartyId:ec.user.userAccount?.partyId ?: '',
                    amendmentDate:ec.user.nowTimestamp, reason:reason,
                    changeType:'QTY_CHANGE', itemSeqId:itemSeqId,
                    productId:item.productId, productName:item.productName ?: item.productId,
                    oldValue:'Qty: '+oldQty, newValue:'Qty: '+newQty,
                    oldGrandTotal:oldGrand, newGrandTotal:txnAfter.grandTotal ?: 0]).call()
        } else if (editType == 'PRICE_CHANGE') {
            def item = ec.entity.find("zenith.erp.pos.PosTransactionItem")
                .condition("transactionId", txId).condition("itemSeqId", itemSeqId).one()
            if (!item) throw new IllegalStateException('Item not found; reload the bill.')
            def oldPrice = item.unitPrice as BigDecimal
            def newPrice = editedValue
            def q = (item.quantity ?: 1) as BigDecimal
            def ls = q * newPrice
            def dp = (item.discountPercent ?: 0) as BigDecimal
            def da = ls * dp / 100
            def originalNet=((item.quantity ?: 0) as BigDecimal)*((item.unitPrice ?: 0) as BigDecimal)-((item.discountAmount ?: 0) as BigDecimal)
            def taxableFraction=originalNet>0 ? ((item.taxableAmount ?: 0) as BigDecimal)/originalNet : BigDecimal.ONE
            def ta = (ls - da) * taxableFraction
            def taxR = BigDecimal.ZERO
            if (item.totalTaxAmount != null && item.taxableAmount != null && (item.taxableAmount as BigDecimal) != 0) {
                taxR = (item.totalTaxAmount as BigDecimal) / (item.taxableAmount as BigDecimal)
            }
            def tt = ta * taxR
            def lt = ta + tt
            ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")
                .parameters([transactionId:txId, itemSeqId:itemSeqId,
                    unitPrice:newPrice, discountAmount:da, taxableAmount:ta,
                    totalTaxAmount:tt, lineTotal:lt]).call()
            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")
                .parameters([transactionId:txId]).call()
            def txnAfter = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
            ec.service.sync().name("create#zenith.erp.pos.PosTransactionAmendment")
                .parameters([transactionId:txId,
                    amendedByPartyId:ec.user.userAccount?.partyId ?: '',
                    amendmentDate:ec.user.nowTimestamp, reason:reason,
                    changeType:'PRICE_CHANGE', itemSeqId:itemSeqId,
                    productId:item.productId, productName:item.productName ?: item.productId,
                    oldValue:'Price: '+oldPrice, newValue:'Price: '+newPrice,
                    oldGrandTotal:oldGrand, newGrandTotal:txnAfter.grandTotal ?: 0]).call()
        } else if (editType == 'ITEM_REMOVED') {
            def item = ec.entity.find("zenith.erp.pos.PosTransactionItem")
                .condition("transactionId", txId).condition("itemSeqId", itemSeqId).one()
            if (!item) throw new IllegalStateException('Item not found; reload the bill.')
            def removedName = item.productName ?: item.productId
            def removedQty = item.quantity
            invAdjProduct = item.productId; invAdjQty = (removedQty ?: 0) as BigDecimal
            ec.service.sync().name("delete#zenith.erp.pos.PosTransactionItem")
                .parameters([transactionId:txId, itemSeqId:itemSeqId]).call()
            ec.entity.find('zenith.erp.tax.TaxLineDetail').condition('referenceType','PosTransactionItem')
                .condition('referenceId',txId).condition('referenceSeqId',itemSeqId).deleteAll()
            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")
                .parameters([transactionId:txId]).call()
            def txnAfter = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
            ec.service.sync().name("create#zenith.erp.pos.PosTransactionAmendment")
                .parameters([transactionId:txId,
                    amendedByPartyId:ec.user.userAccount?.partyId ?: '',
                    amendmentDate:ec.user.nowTimestamp, reason:reason,
                    changeType:'ITEM_REMOVED', itemSeqId:itemSeqId,
                    productId:item.productId, productName:removedName,
                    oldValue:removedName+' x'+removedQty, newValue:'REMOVED',
                    oldGrandTotal:oldGrand, newGrandTotal:txnAfter.grandTotal ?: 0]).call()
        } else if (editType == 'ITEM_ADDED') {
            def productId = editOp.productId
            def addQty = editedValue
            def prod = ec.entity.find("mantle.product.Product").condition("productId", productId).one()
            if (!prod || prod.ownerPartyId != txn.organizationPartyId) throw new IllegalStateException('Product is not available for this organization.')
            def unitPrice = BigDecimal.ZERO
            if (prod.mrpAmount) unitPrice = prod.mrpAmount as BigDecimal
            if (unitPrice == BigDecimal.ZERO) {
                def pp = ec.entity.find("mantle.product.ProductPrice").condition("productId", productId).condition("priceTypeEnumId", "PptList").orderBy("-lastUpdatedStamp").limit(1).one()
                if (!pp) pp = ec.entity.find("mantle.product.ProductPrice").condition("productId", productId).condition("priceTypeEnumId", "PptCurrent").orderBy("-lastUpdatedStamp").limit(1).one()
                if (pp?.price) unitPrice = pp.price as BigDecimal
            }
            if (editOp.newPrice != null && editOp.newPrice.toString().trim()) unitPrice = new BigDecimal(editOp.newPrice.toString())
            if (unitPrice <= 0) { throw new IllegalStateException('Set a product price above ₹0 before adding it to an issued bill.') }
            def newSeqId = String.format("%05d", ++nextItemSeq)
            _addedSeqId = newSeqId
            invAdjProduct = productId; invAdjQty = BigDecimal.ZERO - addQty
            def ls = addQty * unitPrice
            // Preserve the issued bill's tax state, including when earlier edits in
            // this batch removed every old line. Use the same tax service as checkout.
            def taxAmt = BigDecimal.ZERO
            def taxable = ls
            def taxedItem = null
            if (billHasTax) {
                def taxResult = ec.service.sync().name('zenith.tax.TaxServices.calculate#Tax').parameters([
                    organizationPartyId:txn.organizationPartyId,
                    items:[[productId:productId, productTaxCode:prod.productTaxCode,
                        taxCategoryId:prod.taxCategoryId, quantity:addQty, unitAmount:unitPrice,
                        discountAmount:BigDecimal.ZERO, isTaxInclusive:'N']],
                    originRegionGeoId:txn.originRegionGeoId,
                    destinationRegionGeoId:txn.destinationRegionGeoId,
                    transactionType:'SALE']).call()
                if (ec.message.hasError()) throw new IllegalStateException(ec.message.errorsString ?: 'Cannot calculate tax for the added product.')
                taxedItem = taxResult?.taxedItems ? taxResult.taxedItems[0] : null
                taxable = (taxedItem?.taxableAmount != null ? taxedItem.taxableAmount : ls) as BigDecimal
                taxAmt = (taxedItem?.totalTaxAmount ?: 0) as BigDecimal
            }
            def lineTotal = taxable + taxAmt
            ec.service.sync().name("create#zenith.erp.pos.PosTransactionItem")
                .parameters([transactionId:txId, itemSeqId:newSeqId, productId:productId,
                    productName:prod.printName ?: prod.productName ?: productId, productTaxCode:prod.productTaxCode,
                    quantity:addQty, unitPrice:unitPrice, taxableAmount:taxable, totalTaxAmount:taxAmt,
                    lineTotal:lineTotal, discountPercent:0, discountAmount:0]).call()
            if (taxedItem?.taxBreakdowns) {
                ec.service.sync().name('zenith.tax.TaxServices.store#TaxLineDetails').parameters([
                    referenceType:'PosTransactionItem', referenceId:txId, referenceSeqId:newSeqId,
                    taxBreakdowns:taxedItem.taxBreakdowns]).call()
            }
            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")
                .parameters([transactionId:txId]).call()
            def txnAfter = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
            ec.service.sync().name("create#zenith.erp.pos.PosTransactionAmendment")
                .parameters([transactionId:txId,
                    amendedByPartyId:ec.user.userAccount?.partyId ?: '',
                    amendmentDate:ec.user.nowTimestamp, reason:reason,
                    changeType:'ITEM_ADDED', itemSeqId:newSeqId,
                    productId:productId, productName:prod.productName ?: productId,
                    oldValue:'N/A', newValue:(prod.productName ?: productId)+' x'+addQty+' @'+unitPrice,
                    oldGrandTotal:oldGrand, newGrandTotal:txnAfter.grandTotal ?: 0]).call()
        }
        if (['QTY_CHANGE','PRICE_CHANGE'].contains(editType)) {
            def changedLine=ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',txId).condition('itemSeqId',itemSeqId).one()
            def details=ec.entity.find('zenith.erp.tax.TaxLineDetail').condition('referenceType','PosTransactionItem').condition('referenceId',txId).condition('referenceSeqId',itemSeqId).list()
            details.each { detail -> detail.taxableAmount=changedLine.taxableAmount;detail.taxAmount=((changedLine.taxableAmount ?: 0) as BigDecimal)*((detail.taxRate ?: 0) as BigDecimal)/100;detail.update() }
        }
        def txnFinal = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
        def itemsFinal = ec.entity.find("zenith.erp.pos.PosTransactionItem")
            .condition("transactionId", txId).orderBy("itemSeqId").list()
        // Keep the linked Sales invoice consistent with the amended bill so revenue/GST reports stay correct.
        // Rebuilt in-place (same transaction) because the amended items are not yet committed for a force-new sync.
        if (txnFinal?.linkedInvoiceId) {
            def _iid = txnFinal.linkedInvoiceId
            def _inv = ec.entity.find("mantle.account.invoice.Invoice").condition("invoiceId", _iid).one()
            if (_inv) {
                _inv.statusId = "InvoiceInProcess"; _inv.update()
                ec.entity.find("zenith.erp.tax.TaxLineDetail").condition("referenceType","InvoiceItem").condition("referenceId",_iid).deleteAll()
                ec.entity.find("mantle.account.invoice.InvoiceItem").condition("invoiceId",_iid).deleteAll()
                for (li in itemsFinal) {
                    def _ii = ec.service.sync().name("mantle.account.InvoiceServices.create#InvoiceItem").parameters([
                        invoiceId:_iid, itemTypeEnumId:"ItemProduct", productId:li.productId,
                        description:li.productName, quantity:li.quantity, amount:li.unitPrice]).call()
                    ec.service.sync().name("update#mantle.account.invoice.InvoiceItem").parameters([
                        invoiceId:_iid, invoiceItemSeqId:_ii.invoiceItemSeqId, productTaxCode:li.productTaxCode,
                        taxableAmount:li.taxableAmount, totalTaxAmount:li.totalTaxAmount, discountAmount:li.discountAmount]).call()
                    def _tlds = ec.entity.find("zenith.erp.tax.TaxLineDetail").condition("referenceType","PosTransactionItem")
                                  .condition("referenceId",txId).condition("referenceSeqId",li.itemSeqId).orderBy("sequenceNum").list()
                    if (_tlds) {
                        def _bds = _tlds.collect { [taxAuthorityId:it.taxAuthorityId, taxRateId:it.taxRateId, taxCategoryId:it.taxCategoryId,
                            taxName:it.taxName, taxRate:it.taxRate, taxableAmount:it.taxableAmount, taxAmount:it.taxAmount,
                            isIncludedInPrice:it.isIncludedInPrice, countryGeoId:it.countryGeoId, regionGeoId:it.regionGeoId] }
                        ec.service.sync().name("zenith.tax.TaxServices.store#TaxLineDetails").parameters([
                            referenceType:"InvoiceItem", referenceId:_iid, referenceSeqId:_ii.invoiceItemSeqId,
                            parentReferenceType:"Invoice", parentReferenceId:_iid, currencyUomId:"INR", taxBreakdowns:_bds]).call()
                    }
                }
                def _inv2 = ec.entity.find("mantle.account.invoice.Invoice").condition("invoiceId", _iid).one()
                _inv2.invoiceTotal = txnFinal.grandTotal
                _inv2.unpaidTotal = ((txnFinal.grandTotal ?: 0) as BigDecimal) - ((_inv2.appliedPaymentsTotal ?: 0) as BigDecimal)
                _inv2.totalTaxableAmount = txnFinal.subtotal
                _inv2.totalTaxAmount = txnFinal.totalTaxAmount
                _inv2.roundOffAmount = txnFinal.roundOff
                _inv2.statusId = "InvoiceFinalized"
                _inv2.update()
            }
        }
        // Adjust stock by the edit delta (return to / take from stock) -- tracked products only
        if (invAdjProduct && invAdjQty != BigDecimal.ZERO) {
            def _pT = ec.entity.find("mantle.product.Product").condition("productId", invAdjProduct).one()
            if (_pT?.inventoryTracked == 'Y') {
                try {
                    ec.service.sync().name("zenith.inventory.InventoryStockServices.adjust#AssetOnHand").parameters([
                        organizationPartyId: txnFinal.organizationPartyId, productId: invAdjProduct,
                        quantityDiff: invAdjQty, reason: ('Bill edit ' + (txnFinal.transactionNumber ?: txId))]).call()
                } catch (Throwable e) { throw new IllegalStateException('Bill-edit stock adjustment failed; no changes were saved.', e) }
            }
        }
        // Payment reconciliation: refund (paid > new total) or extra collection (new total > paid)
        def _paid = (txnFinal.paidAmount ?: 0) as BigDecimal
        def _pay = (txnFinal.payableAmount ?: 0) as BigDecimal
        def _refundDue = BigDecimal.ZERO; def _balanceDue = BigDecimal.ZERO
        if (_paid > _pay) { _refundDue = _paid - _pay } else if (_pay > _paid) { _balanceDue = _pay - _paid }
        ec.service.sync().name("update#zenith.erp.pos.PosTransaction").parameters([transactionId:txId, changeAmount:_refundDue]).call()
        def paymentsFinal = ec.entity.find("zenith.erp.pos.PosPayment")
            .condition("transactionId", txId).list()
        def amendsFinal = ec.entity.find("zenith.erp.pos.PosTransactionAmendment")
            .condition("transactionId", txId).orderBy("-amendmentDate").list()
        def names = ec.service.sync().name('zenith.pos.PosServices.get#PosDisplayNames')
            .parameter('productIds',(itemsFinal + amendsFinal)*.productId).call().names ?: [:]
        revision = [success:true, action:'amendBill',
            bill:[txId:txId, billNo:txnFinal.transactionNumber ?: txId,
                grand:txnFinal.grandTotal ?: 0, payable:txnFinal.payableAmount ?: 0,
                refundDue:_refundDue, balanceDue:_balanceDue, newSeq:_addedSeqId,
                subtotal:txnFinal.subtotal ?: 0, tax:txnFinal.totalTaxAmount ?: 0,
                items:itemsFinal.collect { [seq:it.itemSeqId, pid:it.productId,
                    name:names[it.productId] ?: it.productId, qty:it.quantity ?: 0,
                    price:it.unitPrice ?: 0, tax:it.totalTaxAmount ?: 0, total:it.lineTotal ?: 0,
                    discountPercent:it.discountPercent, discountAmount:it.discountAmount, taxableAmount:it.taxableAmount] },
                payments:paymentsFinal.collect { [method:it.paymentMethod ?: '', amount:it.amount ?: 0] },
                amendments:amendsFinal.collect { [date:ec.l10n.format(it.amendmentDate, 'dd/MM hh:mm a'),
                    type:it.changeType ?: '', reason:it.reason ?: '',
                    product:names[it.productId] ?: it.productId ?: '', oldVal:it.oldValue ?: '', newVal:it.newValue ?: ''] }
            ]]
        if (ec.message.hasError()) throw new IllegalStateException(ec.message.errorsString)
    }
    freeState = ec.service.sync().name('zenith.pos.PosFreeItemServices.get#FreeItemApprovalState')
        .parameter('transactionId',txId).call()
    if (freeState?.required) {
        if (!freeItemReason) throw new IllegalStateException('FREE_ITEM_APPROVAL_REQUIRED')
        ec.service.sync().name('zenith.pos.PosFreeItemServices.approve#FreeItems').parameters([
            transactionId:txId,reason:freeItemReason,managerPin:freeItemManagerPin,expectedFingerprint:freeItemFingerprint]).call()
    }
    if (ec.message.hasError()) throw new IllegalStateException(ec.message.errorsString)
} catch (Exception failure) {
    ec.transaction.setRollbackOnly('POS bill amendment failed',failure)
    if (ec.message.hasError()) ec.message.clearErrors()
    revision = [success:false,error:failure.message,needFreeApproval:failure.message?.contains('FREE_ITEM_APPROVAL_REQUIRED'),
        freeItems:freeState?.freeItems,approvalFingerprint:freeState?.approvalFingerprint]
}
